parameters.jsCode:
const raw = $input.first().json;

// Read Ollama response
let content = raw.message?.content;

if (!content) {
  throw new Error("Ollama returned no planning content.");
}

// Parse JSON returned by Qwen
let plan;

try {
  plan = JSON.parse(content);
} catch (error) {
  const match = content.match(/\{[\s\S]*\}/);

  if (!match) {
    throw new Error("Planner returned invalid JSON: " + content.slice(0, 500));
  }

  plan = JSON.parse(match[0]);
}

const queries = Array.isArray(plan.queries)
  ? plan.queries.map(q => String(q).trim()).filter(Boolean).slice(0, 5)
  : [];

if (queries.length === 0) {
  throw new Error("Planner returned no search queries.");
}

return queries.map((query, index) => ({
  json: {
    query,
    queryIndex: index + 1,
    researchGoal: plan.research_goal || "Research task"
  }
}));

