parameters.jsCode:
const items = $input.all();
const seen = new Set();
const sources = [];
const failures = [];
for (const item of items) {
  const data = item.json ?? {};
  if (data.error || data.statusCode >= 400) { failures.push(String(data.error?.message ?? data.message ?? 'Search request failed')); continue; }
  const results = Array.isArray(data.results) ? data.results : (Array.isArray(data.body?.results) ? data.body.results : []);
  for (const r of results) {
    const url = String(r.url ?? '').trim();
    if (!url || seen.has(url)) continue;
    seen.add(url);
    sources.push({title: r.title ?? '', url, content: r.content ?? r.raw_content ?? '', score: r.score ?? null});
  }
}
if (!sources.length) throw new Error('No usable web results were returned. Check Tavily API key, query and connectivity. ' + failures.join(' | '));
return [{json: {sources, sourceCount: sources.length, failedSearches: failures}}];

