const data = $input.first().json;
const report = data.message?.content ?? data.body?.message?.content ?? data.data?.message?.content ?? data.response ?? '';
if (!report) throw new Error('Ollama did not return a report. Check endpoint and model availability.');
const original = $('Validate Research Query').first().json;
const aggregate = $('Deduplicate and Aggregate Sources').first().json;
return [{json: {status: 'completed', researchQuery: original.userQuery, generatedAt: new Date().toISOString(), sourceCount: aggregate.sourceCount, reportMarkdown: String(report).trim(), sources: aggregate.sources, failedSearches: aggregate.failedSearches}}];

const r = $input.first().json;

const report = String(r.reportMarkdown || '');

const required = [
  'Executive Summary',
  'Research Plan',
  'Key Findings',
  'Important Evidence',
  'Actionable Insights',
  'Limitations',
  'Sources'
];

const missingSections = required.filter(
  h => !report.toLowerCase().includes(h.toLowerCase())
);

const citationCount = report.split('[').length - 1;

const sourceLinks =
  (report.split('https://').length - 1) +
  (report.split('http://').length - 1);

const passed =
  missingSections.length === 0 &&
  sourceLinks > 0 &&
  report.length > 500;

return [{
  json: {
    ...r,
    qualityCheck: {
      passed,
      missingSections,
      citationCount,
      sourceLinks,
      reportCharacters: report.length,
      note: passed
        ? 'Required sections and source links detected.'
        : 'Report may be incomplete. Check missing sections and source links.'
    }
  }
}];

